        % next trial
        if all(~spkix)
            continue
        end


        N = histc(obj.clu{prbnum}(curClu).trialtm_aligned(spkix), edges);
        N = N(1:end-1);
        if size(N,2) > size(N,1)
            N = N'; % make sure N is a column vector
        end


        obj.trialdat{prbnum}(:,i,j) = mySmooth(N./params.dt,params.smooth, params.bctype);

        %         % raw spikes
        %         spkN = histc(obj.clu{prbnum}(curClu).trialtm_aligned(spkix), spkedges);
        %         if size(spkN,2) > size(spkN,1)
        %             spkN = spkN'; % make sure N is a column vector
        %         end
        %         spkN(spkN > 1) = 1; % binarize (should only have at most 1 spk in 1 ms bin)
        %         obj.trialspikes{prbnum}(:,i,j) = spkN;

    end
end

end % getSeq
```

**Summary:** Creates binned, smoothed spike data at two levels: (1) PSTH (trial-averaged per condition) with dimensions [time × units × conditions], (2) Single-trial data with dimensions [time × units × trials]. Uses histogram binning with bin width params.dt (default 5ms), normalized by trial count and bin width to get firing rate (spikes/sec). Smooths with Gaussian kernel (params.smooth=15ms) and applies boundary condition handling. Time axis spans params.tmin to params.tmax (default -2.5 to +2.5 sec).

